html:
{%- set orange = "#E8692A" -%}
{%- set hdr = frappe.db.get_value("Print Style", frappe.db.get_single_value("Print Settings", "print_style"), "custom_color") or "#00589c" -%}
{%- set dest = "" -%}
{%- if doc.shipping_address -%}
  {%- set a = frappe.db.get_value("Address", doc.shipping_address, ["city", "country"], as_dict=1) -%}
  {%- set dest = (a.city ~ ", " ~ a.country) if a and a.city else doc.shipping_address -%}
{%- elif doc.set_warehouse -%}
  {%- set dest = doc.set_warehouse -%}
{%- endif -%}
<style>
  .po-wrap { font-family: "Century Gothic", Arial, sans-serif; color:#000; }
  .po-frame { border:1.5px solid {{ orange }}; border-radius:16px; padding:14px 14px 18px 14px; }
  .po-title { font-size:24px; font-weight:bold; text-decoration:underline; letter-spacing:0.5px; }
  .po-meta td { font-size:14px; padding:0 0 0 6px !important; }
  .po-box { width:100%; border:1.5px solid #000; border-collapse:collapse; margin-top:4px; }
  .po-box td { vertical-align:top; font-size:13px; }
  .po-cell { border-bottom:1px solid #000; text-align:center; padding:3px !important; }
  .po-items { width:100%; border-collapse:collapse; margin-top:8px; border:1.5px solid #000; }
  .po-items th { border:1px solid #000; text-align:center; font-size:13px; padding:3px !important; font-weight:bold; background:{{ hdr }} !important; color:#fff !important; -webkit-print-color-adjust:exact; print-color-adjust:exact; }
  .po-items td { border:1px solid #000; font-size:12px; padding:2px 4px !important; }
  .po-total td { font-weight:bold; font-size:13px; border-top:1.5px solid #000; border-bottom:3px double #000; }
  .po-pt { width:100%; border-collapse:collapse; margin-top:10px; }
  .po-pt th, .po-pt td { border:1px solid #000; font-size:12px; padding:3px 4px !important; }
  .po-pt th { text-align:center; background:{{ hdr }} !important; color:#fff !important; -webkit-print-color-adjust:exact; print-color-adjust:exact; }
  .po-notes { font-size:11px; }
  .po-notes p, .po-notes li { margin:0 0 3px 0; }
  .po-notes ul { padding-left:0; list-style:none; }
  /* compact */ .po-frame { padding:10px 12px 12px 12px !important; -webkit-box-decoration-break:clone; box-decoration-break:clone; }
  .po-notes ul, .po-notes ol { margin:0 !important; padding-left:14px !important; }
  .po-notes li, .po-notes p { margin:0 !important; line-height:1.3 !important; font-size:11px !important; }
  .po-items { margin-top:6px !important; } .po-pt { margin-top:4px !important; }
  /* compact3 */ .po-notes li, .po-notes p { line-height:1.15 !important; } .po-frame { padding-bottom:6px !important; } .po-wrap > div:first-child img { max-height:30mm; }
  /* compact2 */ .po-items td { padding:1px 4px !important; } .po-items th { padding:2px !important; } .po-pt td, .po-pt th { padding:1px 4px !important; } .po-box td { line-height:1.25 !important; } .po-cell { padding:2px !important; }
  .po-sig1 { margin-top:10px !important; } .po-sig2 { margin-top:32px !important; }
  @page { margin-bottom: 38mm !important; }
  @media screen { #footer-html .lh-page, #footer-html .pf-page { display:none; } }  #footer-html { margin-top:10px; }
</style>

<div class="po-wrap">
{% if letter_head and not no_letterhead %}{{ letter_head }}{% endif %}

<div class="po-frame">
  <table style="width:100%;"><tr>
    <td style="vertical-align:bottom;"><span class="po-title">PURCHASE ORDER</span></td>
    <td style="text-align:right;">
      <table class="po-meta" style="margin-left:auto;">
        <tr><td style="text-align:right;">Date :</td><td style="text-align:right;font-weight:bold;">{{ frappe.utils.formatdate(doc.transaction_date, "dd-MMM-yyyy") }}</td></tr>
        <tr><td style="text-align:right;">Purchase Order No. :</td><td style="text-align:right;font-weight:bold;">{{ doc.name }}</td></tr>
      </table>
    </td>
  </tr></table>

  <table class="po-box"><tr>
    <td style="width:67%; border-right:1px solid #000; padding:4px !important;">
      <div style="font-weight:bold;">To,</div>
      <div style="font-weight:bold;">{{ doc.supplier_name or doc.supplier }}</div>
      {% if doc.address_display %}<div>{{ doc.address_display }}</div>{% endif %}
      {% if doc.contact_display %}<div>Attn :- {{ doc.contact_display }}</div>{% endif %}
    </td>
    <td style="width:33%; padding:0 !important;">
      <div class="po-cell">Dispatch Through<br><b>{{ doc.custom_dispatch_through or "" }}</b></div>
      <div class="po-cell">Destination<br><b>{{ dest }}</b></div>
      <div class="po-cell" style="border-bottom:none;">Terms/Mode of Payment<br><b>{{ doc.payment_terms_template or "" }}</b></div>
    </td>
  </tr></table>

  {%- set ns = namespace(total=0, uoms=[]) -%}
  <table class="po-items">
    <thead><tr>
      <th style="width:6%;">S.<br>No.</th>
      <th style="width:16%;">Pieces<br>Barcode</th>
      <th>Product</th>
      <th style="width:16%;">Packing Size</th>
      <th style="width:15%;">Quantity</th>
    </tr></thead>
    <tbody>
    {%- for row in doc.items -%}
      {%- set bc = row.barcode or frappe.db.get_value("Item Barcode", {"parent": row.item_code}, "barcode") or "" -%}
      {%- set ns.total = ns.total + row.qty -%}
      {%- if row.uom not in ns.uoms -%}{%- set ns.uoms = ns.uoms + [row.uom] -%}{%- endif -%}
      <tr>
        <td style="text-align:center;">{{ row.idx }}</td>
        <td style="text-align:center;">{{ bc }}</td>
        <td>{{ row.item_name }}</td>
        <td style="text-align:right;">{% if row.conversion_factor and row.conversion_factor != 1 %}1 {{ row.uom }} = {{ row.conversion_factor|int if row.conversion_factor == row.conversion_factor|int else row.conversion_factor }} {{ row.stock_uom }}{% endif %}</td>
        <td style="text-align:right;">{{ row.get_formatted("qty") }} {{ row.uom }}</td>
      </tr>
    {%- endfor -%}
    <tr class="po-total">
      <td colspan="4" style="text-align:right;">Total Quantity</td>
      <td style="text-align:right;">{{ frappe.utils.fmt_money(ns.total, precision=0) }}{% if ns.uoms|length == 1 %} {{ ns.uoms[0] }}{% endif %}</td>
    </tr>
    </tbody>
  </table>

  {% if doc.payment_schedule %}
  <div style="margin-top:6px; font-weight:bold; font-size:13px;">Payment Terms</div>
  <table class="po-pt">
    <thead><tr><th>Term</th><th style="width:18%;">Due Date</th><th style="width:10%;">%</th><th style="width:22%;">Amount</th></tr></thead>
    <tbody>
    {% for p in doc.payment_schedule %}
      <tr>
        <td>{{ p.payment_term or p.description or "" }}</td>
        <td style="text-align:center;">{{ frappe.utils.formatdate(p.due_date, "dd-MMM-yyyy") }}</td>
        <td style="text-align:center;">{{ p.invoice_portion|round(2) }}</td>
        <td style="text-align:right;">{{ p.get_formatted("payment_amount", doc) }}</td>
      </tr>
    {% endfor %}
    </tbody>
  </table>
  {% endif %}

  <div style="margin-top:6px;">
    <div style="float:right; width:36%; padding-left:14px; page-break-inside:avoid; break-inside:avoid;">
      <div class="po-sig1" style="font-size:15px; margin-top:22px;">For <b>SABA TRADING GROUP</b></div>
      <div class="po-sig2" style="font-size:15px; font-weight:bold; margin-top:45px;">Authorised Signatory</div>
    </div>
    {% if doc.terms %}
    <div>
      <div style="font-weight:bold; font-size:14px;">Note:</div>
      <div class="po-notes">{{ doc.terms }}</div>
    </div>
    {% endif %}
    <div style="clear:both;"></div>
  </div>
</div>

<div id="footer-html" class="visible-pdf">
  {% if footer and not no_letterhead %}{{ footer }}{% else %}
  <div class="pf-page" style="text-align:right; font-size:11px; font-style:italic;">Page <span class="page"></span> of <span class="topage"></span></div>
  {% endif %}
</div>
</div>
